package com.fersaiyan.cyanbridge.shared.vision

import kotlin.test.Test
import kotlin.test.assertEquals

class ImageResizeTest {
    private class Case(val srcWidth: Int, val srcHeight: Int, val dstWidth: Int, val dstHeight: Int, val rgbHex: String)

    /**
     * Expected = OpenCV 4.10 (x86, pip opencv-python) on the same pattern:
     *   img[y, x] = ((x*37 + y*91 + 11) % 256, (x*x*7 + y*13 + 101) % 256, (x*y*29 + 53) % 256)  # RGB uint8
     *   cv2.resize(img, (dstWidth, dstHeight), interpolation=cv2.INTER_LINEAR).tobytes().hex()
     * Upscale, downscale, exact 2x down (cv2 switches to its area path there), mixed, 1x1.
     */
    private val cases = listOf(
        Case(13, 7, 29, 11, ""),
        Case(40, 30, 17, 9, ""),
        Case(64, 32, 32, 16, ""),
        Case(5, 3, 9, 48, ""),
        Case(1, 1, 3, 2, "0b65350b65350b65350b65350b65350b6535"),
        Case(6, 9, 4, 20, ""),
    )

    private fun pattern(w: Int, h: Int) = IntArray(w * h) { i ->
        val x = i % w
        val y = i / w
        (0xFF shl 24) or (((x * 37 + y * 91 + 11) % 256) shl 16) or (((x * x * 7 + y * 13 + 101) % 256) shl 8) or
            ((x * y * 29 + 53) % 256)
    }

    @Test
    fun matchesOpenCvInterLinearBitExactly() {
        for (c in cases) {
            val out = ImageResize.bilinearArgb(pattern(c.srcWidth, c.srcHeight), c.srcWidth, c.srcHeight, c.dstWidth, c.dstHeight)
            val hex = StringBuilder()
            for (p in out) {
                for (shift in intArrayOf(16, 8, 0)) hex.append(((p shr shift) and 0xFF).toString(16).padStart(2, '0'))
            }
            assertEquals(c.rgbHex, hex.toString(), "${c.srcWidth}x${c.srcHeight} -> ${c.dstWidth}x${c.dstHeight}")
        }
    }

    @Test
    fun sameSizeIsACopyAndOutputIsOpaque() {
        val src = pattern(7, 5).map { it and 0x00FFFFFF }.toIntArray()
        val out = ImageResize.bilinearArgb(src, 7, 5, 7, 5)
        assertEquals(src.map { it or (0xFF shl 24) }, out.toList())
    }
}
